export function isField(name: string | null | undefined): name is string {
  return !!name && Object.hasOwn(FIELDS, name);
}

export function fieldLabel(name: string | null | undefined): string {
  if (!name) return "";
  return LABELS[name] ?? name;
}

export function formatValue(field: string | null | undefined, value: unknown): string {
  if (value === null || value === undefined || value === "") return "—";
  const spec = isField(field) ? FIELDS[field] : null;
  // values stored as text (corrected_value, listing JSON) are shown like the typed ones
  if (typeof value === "string" && spec?.kind === "bool" && (value === "true" || value === "false")) {
    value = value === "true";
  } else if (
    typeof value === "string" &&
    (spec?.kind === "int" || spec?.kind === "float") &&
    Number.isFinite(Number(value))
  ) {
    value = Number(value);
  }
  if (typeof value === "boolean") return value ? "Sí" : "No";
  const unit = spec?.unit ?? null;
  if (typeof value === "number") return unit ? `${value} ${unit}` : String(value);
  if (typeof value === "string") return value;
  return JSON.stringify(value);
}

export type ValidationResult = { ok: true; value: string } | { ok: false; error: string };

/** Checks a reviewer's corrected value against the field's type and range. The worker checks
 *  it again in Python (same catalog); this only gives the reviewer an immediate answer. */
export function validateFieldValue(field: string, raw: string): ValidationResult {
  const spec = FIELDS[field];
  const text = raw.trim();
  if (!spec) return { ok: false, error: `Campo desconocido: ${field}` };
  if (!text) return { ok: false, error: "Escribe el valor correcto." };

  switch (spec.kind) {
    case "bool": {
      const v = text.toLowerCase();
      if (["true", "sí", "si", "yes"].includes(v)) return { ok: true, value: "true" };
      if (["false", "no"].includes(v)) return { ok: true, value: "false" };
      return { ok: false, error: "Elige Sí o No." };
    }
    case "enum":
      return spec.values?.includes(text)
        ? { ok: true, value: text }
        : { ok: false, error: `Debe ser uno de: ${spec.values?.join(", ")}.` };
    case "int":
    case "float": {
      const n = Number(text.replace(",", "."));
      if (!Number.isFinite(n) || !/^-?\d+([.,]\d+)?$/.test(text)) {
        return { ok: false, error: `Escribe solo el número${spec.unit ? ` en ${spec.unit}` : ""}.` };
      }
      if (spec.kind === "int" && !Number.isInteger(n)) {
        return { ok: false, error: "Debe ser un número entero." };
      }
      if (spec.range && (n < spec.range[0] || n > spec.range[1])) {
        const [lo, hi] = spec.range;
        return {
          ok: false,
          error: `Fuera de rango: entre ${lo} y ${hi}${spec.unit ? ` ${spec.unit}` : ""}.`,
        };
      }
      return { ok: true, value: String(n) };
    }
    default:
      return text.length <= 100 ? { ok: true, value: text } : { ok: false, error: "Máximo 100 caracteres." };
  }
}
